param([Parameter(Mandatory=$true)][string]$NodeExecutable,[Parameter(Mandatory=$true)][string]$Script,[Parameter(Mandatory=$true)][string]$Config,[Parameter(Mandatory=$true)][string]$OutputDirectory)
$ErrorActionPreference='Stop';if(Test-Path -LiteralPath $OutputDirectory){throw 'Fresh hidden IPC output required'};[void](New-Item -ItemType Directory -Path $OutputDirectory);$arguments=@('-NoProfile','-NonInteractive','-File',$Script,'-NodeExecutable',$NodeExecutable,'-Config',$Config,'-Output',(Join-Path $OutputDirectory 'report.json'));foreach($v in $arguments){if($v.Contains('"')){throw 'Unexpected quote'}};$quoted=@($arguments|ForEach-Object{'"'+$_+'"'});$p=Start-Process -FilePath (Join-Path $env:SystemRoot 'System32/WindowsPowerShell/v1.0/powershell.exe') -WindowStyle Hidden -ArgumentList $quoted -RedirectStandardOutput (Join-Path $OutputDirectory 'stdout.log') -RedirectStandardError (Join-Path $OutputDirectory 'stderr.log') -PassThru;$null=$p.Handle
try{$done=$p.WaitForExit(30000);$r=[ordered]@{finished=$done;status=$null;ownedPureHelperProcessId=$p.Id;officeInvoked=$false;realProcessQueries=0};if($done){$r.status=$p.ExitCode};$r|ConvertTo-Json -Depth 10|Set-Content -LiteralPath (Join-Path $OutputDirectory 'exit.json') -Encoding UTF8;if(-not $done -or $p.ExitCode -ne 0){throw 'Hidden pure IPC test failed; preserve outputs/no retry'}}finally{$p.Dispose()}
